-- Rifts World Book 21: Splynn Dimensional Market - its bestiary and its notable NPCs.
-- 5 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~373-splynn-creatures-c.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 creatures are in' AS assertion, count(*) AS got, 5 AS want
  FROM creatures WHERE slug IN ('staphra-warrior', 'staphra-warlord', 'staphra-mystic', 'were-dragon', 'monster-were-dragon');
SELECT 'and 5 of them are playable' AS assertion, count(*) AS got, 5 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('staphra-warrior', 'staphra-warlord', 'staphra-mystic', 'were-dragon', 'monster-were-dragon');
SELECT 'the creatures carry 13 attacks' AS assertion, count(*) AS got, 13 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('staphra-warrior', 'staphra-warlord', 'staphra-mystic', 'were-dragon', 'monster-were-dragon');

