INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('staphra-warrior', 'Staphra Warrior', 'humanoid', 'rifts', 1, 'Any; most NPCs are aberrant or anarchist, and player characters lean anarchist or unprincipled.', '{"IQ":"2D6+4","ME":"3D6+2","MA":"2D6","PS":"4D6+6","PP":"3D6+6","PE":"3D6+8","PB":"2D6","Spd":"4D6+6"}', 'PE', '2D6x10', NULL, '4D6', '1D6x10+ME', 'An S.D.C. being who needs armor or magic for M.D.C. protection. Hit Points are the P.E. attribute number plus 2D6 per level of experience; S.D.C. is 2D6x10 plus any from physical skills. P.P.E. is 4D6. I.S.P. is 1D6x10 plus the M.E. attribute number, plus 1D6+1 per level after the first.', NULL, 9, '{"initiative":3,"strike":1,"parry":2,"dodge":2,"pull":5,"roll":3}', 'Attacks per melee come from her hand to hand skill (Expert, which the class may upgrade). Printed R.C.C. bonuses, on top of attribute and skill bonuses: +3 initiative, +1 strike, +2 parry and dodge, +5 pull punch, +3 roll with punch or impact, +2 disarm, +1 save vs magic and poison, +3 save vs mind control and possession, and +1 save vs Horror Factor at levels 1, 3, 4, 6, 7, 8, 10, 12 and 15.', 'The R.C.C. skills, the eight related and four secondary skills with their later additions, and the Headhunter experience table belong to the Staphra Warrior class, not this row.', 'Nightvision to 500 feet (152.4 m). A keen nose: tracks by scent at 60% (+10% on a blood trail) and knows common odors at 75%. Ambidextrous, fast reflexes, very supple, and shrugs off pain.', 'None.', 'Major psychic; needs 12 or higher to save vs psionics. Telekinetic Punch, Telekinetic Leap, Resist Fatigue, Resist Hunger, Resist Thirst, Impervious to Fire, Impervious to Cold, Impervious to Poison, Mind Block, Summon Inner Strength and Suppress Fear.', '7-8 feet (2.1-2.4 m) tall', '350-500 lbs (157.5-225 kg), all hard muscle', '70 years', 'Wherever the Splugorth hold sway; by nature, forest and grassland.', 'The Minions of Splugorth, whose ally she counts herself though her race is still slave stock; only the Kittani and the Altara Warrior Women treat her as nearly an equal. The book expects the Warriors and the male Mystics to reach full Minion status within 3D4 years.', 'Every enemy of the Splugorth. A renegade counts her own people, the Splugorth and their Minions as foes, and they return the feeling.', 'None; an R.C.C. (the Staphra Warrior class). Offered as an NPC villain or apprentice Minion and as an optional player character, who must be either a Splugorth spy or a deserter.', 'A tall, lean, green-skinned humanoid woman with a mane of black or dark red hair, usually braided, red to yellow eyes and broad slit nostrils that give her a superb nose. Among the Staphra every warrior is female (females outnumber males five to one); she trains for battle from infancy and is expected to hunt and fight by her early teens. She is proud, quick to anger, orderly and merciless in a fight, and a sharp tactician. Her people were a primitive psychic race whom the Splugorth judged too weak for Minion rank and enslaved; a century on, most Staphra strive to earn that rank, and the Kittani now favor them. Her prized weapon is the traditional double spear, a short glaive with a blade at each end, now fitted with Vibro-Blades (3D6 M.D., +1 to parry and disarm, +1 to strike when spun and hurled); she is issued light and medium body armor. She loves Bio-Wizard and magic weapons, though only officers and an elite get them, and never takes cybernetics. Value: only rogues and the disobedient are sold, typically for 30,000-50,000 credits, sometimes twice that.', 'Rifts World Book 21: Splynn Dimensional Market p.90-93'),
('staphra-warlord', 'Staphra Warlord', 'humanoid', 'rifts', 1, 'Any; most NPCs are aberrant or anarchist, and player characters lean anarchist or unprincipled.', '{"IQ":"2D6+4","ME":"2D6+8","MA":"1D6+4","PS":"2D6+24","PP":"2D6+12","PE":"2D6+14","PB":"2D6","Spd":"4D6+20"}', NULL, NULL, '50+5D6', '4D6', NULL, 'A lesser supernatural being with 50+5D6 M.D.C., over which M.D.C. body armor may be worn. She can raise her M.D.C. by 15 per level of experience for 15 minutes at a time, up to twice per level in any 24 hours. P.P.E. is 4D6. The book gives her no I.S.P. pool, though Psi-Channeling and its energy bolt are each priced at 2 I.S.P. a use (natural abilities).', NULL, 13, '{"initiative":4,"strike":1,"parry":1,"dodge":1,"pull":6,"roll":3}', 'Attacks come from her hand to hand skill (Martial Arts or Assassin) plus one from the R.C.C. Printed R.C.C. bonuses, on top of attribute and skill bonuses: +1 attack per melee, +4 initiative, +1 strike, parry and dodge, +6 pull punch, +3 roll with punch or impact, +2 disarm, +2 save vs magic, +3 save vs mind control, +6 save vs possession, and +1 save vs Horror Factor at levels 1, 2, 3, 4, 6, 7, 8, 10, 11, 12 and 15. Her P.S. is supernatural, and her physical attributes do not rise with physical skills. Her usual P.P. and combat bonuses apply to a Psi-Channeled weapon; the energy bolt is +1 to strike and takes no other bonus.', 'The R.C.C. skills, the six related and two secondary skills with their later additions, and the Bio-Borg experience table belong to the Staphra Warlord class, not this row.', 'Senses as the Warrior''s: nightvision to 500 feet (152.4 m), tracks by scent at 60% (+10% on blood), knows common odors at 75%; ambidextrous, quick, supple and hard to hurt. Four numbered abilities come from her Bio-Borg conversion, driven by a small round organism at the base of her skull that turns her psionics inward. (1) An M.D.C. body (pools). (2) Supernatural strength, speed and endurance: she does Mega-Damage barehanded, needs only three hours of sleep a day, and stays fully alert for 24 hours per level of experience without any; after a brief run-up she can jump 50 feet (15.2 m) across or 25 feet (7.6 m) up, and half as far from standing. (3) Her old resistance powers are now permanent: impervious to fire, cold and poison, with better saves vs magic, possession and Horror Factor (the bonuses). (4) Psi-Channeling: she charges any non-magic object she holds, usually an unpowered copy of the double spear, knife or sword, into a Mega-Damage weapon (attacks). Charging takes one melee attack and 2 I.S.P., and holds for 15 minutes per level before a ten-minute rest, at 2 I.S.P. per further 15 minutes; bursts of no more than five minutes per level can go on indefinitely. From the same channelled force she can fire an energy bolt (attacks) at 2 I.S.P. a shot.', 'None.', 'None as such: the conversion turns the Warrior''s powers into the four special abilities under natural abilities.', '8-9 feet (2.4-2.7 m) tall', '350-500 lbs (157.5-225 kg), all muscle', '55 years', 'Wherever the Splugorth hold sway; by nature, forest and grassland.', 'As the Warrior''s; Kydian Overlords in particular warm to the Warlords as kindred spirits.', 'Every enemy of the Splugorth.', 'None; an R.C.C. (the Staphra Warlord class). Offered as an NPC villain or apprentice Minion and as an optional player character on the same terms as the Warrior.', 'A Staphra Warrior picked for Bio-Borg conversion, the Splugorth''s next step for the race toward Minion status, as they did with the Kydian Powerlords and the Conservators. She is taller and heavier with muscle than a Warrior and carries a small round organism grafted to the back of her skull; it was bred for her race alone and cannot be fitted to anyone else. The Warlords are the elite of their people: each is issued two suits of armor, a medium one of 60 M.D.C. and a heavy one of 100 M.D.C., and a lesser Bio-Wizard pistol, and their commanders a Staff of All Seeing or a Staff of Pacification. No cybernetics or bionics. Value: only rogues and the disobedient are sold, for 100,000-300,000 credits or a little more.', 'Rifts World Book 21: Splynn Dimensional Market p.93-95'),
('staphra-mystic', 'Staphra Mystic', 'humanoid', 'rifts', 1, 'Any; most NPCs are aberrant or anarchist, and player characters lean anarchist or unprincipled.', '{"IQ":"2D6+8","ME":"3D6+8","MA":"2D6+6","PS":"2D6+4","PP":"2D6+3","PE":"2D6+2","PB":"2D6","Spd":"3D6"}', 'PE', '4D6', NULL, '1D6x10+PE', '1D6x10+ME', 'An S.D.C. being. Hit Points are the P.E. attribute number plus 1D6 per level of experience; S.D.C. is 4D6 plus any from skills. P.P.E. is 1D6x10 plus the P.E. attribute number, plus 2D6 per level after the first. I.S.P. is 1D6x10 plus the M.E. attribute number, plus 1D6+1 per level after the first.', NULL, NULL, '{"initiative":1,"pull":2,"roll":2}', 'Attacks come from his hand to hand skill (Basic, which the class may upgrade to Expert). Printed R.C.C. bonuses, on top of the Mystic O.C.C.''s own and of attribute and skill bonuses: +1 initiative, +2 roll with punch or impact, +2 pull punch, +1 save vs Horror Factor, +1 save vs poison and disease. Damage is a human''s. No Horror Factor.', 'The R.C.C. skills, the five related and two secondary skills with their later additions, and the Mystic experience table belong to the Staphra Mystic class, not this row.', 'Nightvision to 500 feet (152.4 m). A good nose, weaker than a female''s: tracks by scent at 50% (+5% on a blood trail) and knows common odors at 65%. Reflexes and physique fair to good, poor beside the females''. He has every power and special ability of the Mystic O.C.C. (Rifts RPG p.85).', 'As the Mystic O.C.C., unchanged.', 'As the Mystic O.C.C. (Rifts RPG p.85): items 1, 2 and 6 unchanged, three items changed. (3) Automatic: Empathy, Healing Touch, Psychic Diagnosis and Psychic Surgery. (4) Three more Healing powers and three Sensitive powers of choice, and one Super-Psionic power at level four. (5) I.S.P. (pools).', '6-6.5 feet (1.8-1.95 m) tall', '120-160 lbs (54-72 kg)', '80 years', 'Wherever the Splugorth hold sway.', 'Much as the Warrior''s, though the males earn less respect than the female warriors and may wait some years longer for Minion rank.', 'Every enemy of the Splugorth.', 'None; an R.C.C. that is a born Mystic (the Staphra Mystic class). Offered as an NPC villain or apprentice Minion and as an optional player character.', 'A Staphra male: human-sized, slim and frail beside the towering females, with the race''s green skin, slit nostrils and a wild, untended mane. The males are their people''s teachers, healers, shamans and keepers of law and custom; they raise the young, cook, make clothing and run the social life of the tribe, and must survive the rough matings of the females, so an old male is honored as much as a warrior chief. Their home world was poor in magic, so they leaned on psychic healing until the Splugorth taught them more of magic and the Megaverse; a Staphra Mystic is a little stronger in psionics than an ordinary Mystic. He avoids cybernetics as unnatural and a hindrance to magic, and mostly keeps clear of Bio-Wizardry too. Value: 700,000 to 1.2 million credits, for his healing and magic.', 'Rifts World Book 21: Splynn Dimensional Market p.95-97'),
('were-dragon', 'Were-Dragon', 'humanoid', 'rifts', 1, 'Any; most ordinary Were-Dragons are unprincipled (30%) or good (42%).', '{"IQ":"2D6+3","ME":"3D6","MA":"3D6+3","PS":"2D6+3","PP":"3D6","PE":"2D6+3","PB":"4D6+3","Spd":"3D6"}', NULL, NULL, '1D4x10+PE', '1D6x10+PE', NULL, 'A Mega-Damage being. In humanoid form M.D.C. is 1D4x10 plus the P.E. attribute number, plus 1D6 per level of experience, and the whole of it doubles in dragon form. On S.D.C. worlds the dragon form has 1D4x100+25 S.D.C. and natural A.R. 12 (the ar column). P.P.E. Base is 1D6x10 plus the P.E. attribute number; an earlier line of the same block gives 6D6+6, and this row takes the P.P.E. Base line. Spd 3D6 is walking speed in humanoid form.', 12, 9, '{"initiative":2,"parry":1,"dodge":1,"pull":2,"roll":1}', 'Attacks come from its hand to hand skill (Basic, which the class may upgrade). Humanoid-form R.C.C. bonuses: +2 initiative, +1 parry and dodge, +2 pull punch, +1 roll with punch or impact, +1 save vs poison, +1 save vs Horror Factor; they add to the dragon-form bonuses and to attribute and skill bonuses. In flight it gains +1 attack per melee, +2 initiative, +1 strike and parry and +3 dodge; the tail adds one attack per melee and is +1 to strike, parry and dodge. Horror Factor 9 is for the dragon form only (none in humanoid form), +2 when it is taken for a real dragon.', 'The R.C.C. skills, the related and secondary skill counts and the Psi-Stalker experience table belong to the Were-Dragon class, not this row.', 'Good color vision and a keen, not superhuman, sense of smell in humanoid form. Metamorphosis: in one melee round it becomes a small winged serpent, a natural change it can hold as long as it likes. The dragon form''s six bonuses: (1) its M.D.C. doubles (on S.D.C. worlds, see pools); (2) +1D4+6 to P.S., not supernatural; (3) hovers and flies at a Spd of 1D4x10+50, rolled once when the character is made, about 40-53 mph (64-85 km); (4) in flight +1 attack per melee, +2 initiative, +1 strike and parry, +3 dodge; (5) a prehensile tail, +1 to strike, parry and dodge with one extra attack per melee, that can grab things and wield simple melee weapons, though skills done with it are at -40%, it strikes at -2 with a hand weapon and fires guns at -6; (6) claws and a bite (attacks).', 'None, other than what Bio-Wizard tampering may give.', 'None.', '5.5-6 feet (1.6-1.8 m) tall and slender in humanoid form; about 12 feet (3.6 m) long as a dragon, half of it tail', '110-135 lbs (49.5-60.8 kg) in humanoid form; double that as a dragon', '70-100 years', 'Wilderness by choice, above all mountains and thick forest, but it turns up anywhere. A few hundred live on Rifts Earth, three of them at Lazlo and one at Tolkeen.', 'Good beings, those close to nature above all (the American Indians among them).', 'Dragons, which have hounded the race for centuries, and the Splugorth, their Minions, demons and other evil supernatural beings. It is wary of dragons, hatchlings included, but bears them no automatic hatred and tries to take everyone as they are.', 'None; an R.C.C. (the Were-Dragon class). Offered as an NPC, a Splugorth slave or an optional player character.', 'A shape-changing alien that is neither a werebeast, a dragon nor quite a creature of magic. In humanoid form it is slight, hairless and lovely, with powder-blue or pale green skin, an egg-shaped head and pupil-less deep blue eyes; its other form is a long serpent with leathery wings, a prehensile tail and scales of shimmering blue or emerald over a white belly. On its mountainous home world the change let it escape predators, and it lived peacefully in hunter-gatherer tribes of 100-400. The Splugorth overran that world within a year and the Kydians settled it; today about 55% of the survivors are slaves, half of them owned by the Splugorth, prized as graceful pets and servants. True dragons, evil ones most of all, despise it as an impostor, torment it and urge its sale, and some hunt the race toward extinction. Gentle by nature, it shuns cybernetics, bionics and symbiotes. Value: 100,000 to 400,000 credits.', 'Rifts World Book 21: Splynn Dimensional Market p.97-101'),
('monster-were-dragon', 'Monster Were-Dragon', 'humanoid', 'rifts', 1, 'Any, though the treatment darkens it (natural abilities): monsters run about 35% good, 30% selfish and 35% evil.', '{"IQ":"2D6+3","ME":"3D6","MA":"3D6+3","PS":"2D6+3","PP":"3D6","PE":"2D6+3","PB":"4D6+3","Spd":"3D6"}', NULL, NULL, '3D4x10+PE', '3D4x10+PE', NULL, 'In humanoid form M.D.C. is 3D4x10 plus the P.E. attribute number, plus 1D6 per level of experience, and the whole of it triples in dragon form. P.P.E. Base is 3D4x10 plus the P.E. attribute number; an earlier line of the same block gives 6D6+60, and this row takes the P.P.E. Base line. The attribute dice are the ordinary Were-Dragon''s, before the penalties: I.Q. and P.B. -30%, M.E. -20%, M.A. halved. Spd 3D6 is walking speed in humanoid form.', NULL, 12, '{"initiative":2,"parry":1,"dodge":1,"pull":2,"roll":1}', 'Attacks come from its hand to hand skill (Expert, which the class may upgrade). Humanoid-form R.C.C. bonuses, as the ordinary Were-Dragon''s: +2 initiative, +1 parry and dodge, +2 pull punch, +1 roll with punch or impact, +1 save vs poison, +1 save vs Horror Factor; they add to the dragon-form bonuses and to attribute and skill bonuses. In flight +1 attack per melee, +3 initiative, +1 strike and parry, +1 dodge; the tail adds one attack per melee and is +1 to strike, parry and dodge; +2 save vs magic and possession in dragon form. Horror Factor 12 in dragon form only, +2 when it is taken for a real dragon.', 'The R.C.C. skills, the related and secondary skill counts and the Bio-Borg experience table belong to the Monster Were-Dragon class, not this row.', 'In humanoid form, good color vision and a keen but not superhuman nose. Its change into the monster form takes one melee round and can be held indefinitely; the Bio-Wizard treatment made it a true creature of magic, though it stays mortal in humanoid form. The ten monster-form abilities: (1) M.D.C. triples; (2) +10 to P.S., which is supernatural in this form only; (3) hovers and flies at a Spd of 1D6x10+62, about 53-75 mph (85-120 km); (4) in flight +1 attack per melee, +3 initiative, +1 strike and parry, +1 dodge; (5) spiked wings; (6) a heavy striking tail, +1 to strike, parry and dodge, with one extra attack, that cannot grasp anything; (7) claws; (8) bite; (9) fire breath, usable once a melee round as an extra attack; (10) +2 save vs magic and possession. The wing, tail, claw, bite and fire damage is under attacks. Five penalties come with the treatment: its alignment darkens (good becomes anarchist or aberrant, unprincipled becomes anarchist or miscreant, anarchist becomes miscreant or diabolic, evil stays evil, and effort may at best win back unprincipled); I.Q. -30%; M.E. -20%; M.A. halved; P.B. -30%. It also gains one rolled craving (description).', 'None, other than what Bio-Wizard tampering may give.', 'None.', '5.5-6 feet (1.6-1.8 m) tall in humanoid form; about 15 feet (4.6 m) long and heavily built as a dragon, half of it tail', 'Humanoid weight is printed only for the ordinary Were-Dragon (110-135 lbs/49.5-60.8 kg); the monster form weighs three times as much', '35-50 years, half an ordinary Were-Dragon''s, worn down by the treatments', 'Wilderness by choice, above all mountains and thick forest, but it turns up anywhere. A couple of dozen are free on Rifts Earth, four of them with the Federation of Magic and two at Tolkeen.', 'Ruthless, powerful beings; about half fall in under anyone of equal or greater power.', 'True dragons, which even it dislikes, and the Splugorth, their Minions, demons and other evil supernatural beings.', 'None; an R.C.C. (the Monster Were-Dragon class). Offered as an NPC, a Splugorth slave or an optional player character.', 'An ordinary Were-Dragon put through a course of agonizing Bio-Wizard treatments; about a third of the race has suffered it. It comes out bulkier, thick- and dark-hided, with spurs jutting from its joints and spine and dark red eyes in either form; as a dragon it is darker and bigger, with blade-edged wings that slice S.D.C. steel with ease and fire on its breath. The treatments also dull its mind and leave it irritable and cruel; calm when left alone, once roused it fights without mercy, and the worst torture for fun. Arena owners, guard masters and Conservators covet it, the last keeping it loyal with mind-controlling symbiotes. Craving or behavior, rolled on percentile: 01-20 lives for violence and killing; 21-40 hungers for humanoid flesh and blood, often eating beaten foes, and is warlike; 41-60 a bully who preys on the weak, gets on with Minions, evil folk and slavers, and respects strength; 61-80 hungry for power and respect, ruthless and even treacherous in getting them; 81-90 childlike and trusting, obeying its master, commander or friends without weighing right or wrong, slow off the mark (no initiative bonus) and savagely protective of those it trusts; 91-00 loathes cruelty, slavery and brutality, avoids violence and killing, and regains 1D4+2 M.A. and 1 I.Q. It is already altered as far as it can be. Value: 800,000 to 1.5 million credits for one that can be controlled.', 'Rifts World Book 21: Splynn Dimensional Market p.98-101');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'staphra-warrior', 'Punch or kick', '2D6', 0, NULL, 'S.D.C., plus any P.S. damage bonus.', 0),
('creature', 'staphra-warlord', 'Supernatural punch', '3D6', 1, NULL, 'M.D. at full strength, typically 3D6 or 4D6 by her supernatural P.S.', 0),
('creature', 'staphra-warlord', 'Psi-Channeled weapon', '1D6', 1, NULL, 'She sets it at 1 M.D., 1D4 M.D. or 1D6 M.D. at level one, +1 M.D. at levels 2, 4, 6, 8, 10, 12 and 14, on top of her punch damage; charging costs one melee attack and 2 I.S.P.', 1),
('creature', 'staphra-warlord', 'Energy bolt', '1D6', 1, '50 feet (15.2 m) per level', 'She sets it at 1 M.D., 1D4 M.D. or 1D6 M.D.; one melee attack, +1 to strike and no other bonus; 2 I.S.P. a blast.', 2),
('creature', 'were-dragon', 'Dragon claws', '3D6', 0, NULL, 'S.D.C., plus P.S. and combat bonuses; dragon form.', 0),
('creature', 'were-dragon', 'Claw power punch', '1D4', 1, NULL, 'M.D.; counts as two attacks; dragon form.', 1),
('creature', 'were-dragon', 'Bite', '2D6', 0, NULL, 'S.D.C.; dragon form.', 2),
('creature', 'monster-were-dragon', 'Wing swipe', '1D6', 1, NULL, 'M.D.', 0),
('creature', 'monster-were-dragon', 'Flying wing slash', '3D6', 1, NULL, 'M.D. plus supernatural P.S. damage, at full speed and strength; counts as two attacks.', 1),
('creature', 'monster-were-dragon', 'Tail strike', '3D6', 1, NULL, 'M.D. at full strength; 6D6 as a power strike, 1D4 M.D. restrained.', 2),
('creature', 'monster-were-dragon', 'Claws', '1D6', 1, NULL, 'M.D. plus supernatural P.S. punch damage.', 3),
('creature', 'monster-were-dragon', 'Bite', '2D6', 1, NULL, 'M.D.', 4),
('creature', 'monster-were-dragon', 'Fire breath', '4D6', 1, '40 feet (12 m)', 'M.D.; once per melee round, as an extra attack.', 5);
INSERT INTO data_script_runs (filename) VALUES ('~373-splynn-creatures-c.sql');
